from __future__ import annotations

import pytest

from app.model_provider import ModelProviderUnavailable, _parse_response


def test_completed_response_preserves_text_and_token_accounting() -> None:
    completion = _parse_response(
        {
            "id": "resp_test",
            "status": "completed",
            "output_text": '{"decision":"cautious"}',
            "usage": {
                "input_tokens": 20,
                "output_tokens": 7,
                "input_tokens_details": {"cached_tokens": 3},
                "output_tokens_details": {"reasoning_tokens": 2},
            },
        }
    )

    assert completion.content == '{"decision":"cautious"}'
    assert completion.input_tokens == 20
    assert completion.output_tokens == 7
    assert completion.cached_input_tokens == 3
    assert completion.reasoning_output_tokens == 2
    assert completion.response_id == "resp_test"


def test_incomplete_response_is_never_treated_as_a_valid_answer() -> None:
    with pytest.raises(ModelProviderUnavailable, match="incomplete"):
        _parse_response(
            {
                "status": "incomplete",
                "incomplete_details": {"reason": "max_output_tokens"},
            }
        )


def test_refusal_is_never_treated_as_an_empty_or_valid_answer() -> None:
    with pytest.raises(ModelProviderUnavailable, match="declined"):
        _parse_response(
            {
                "status": "completed",
                "output": [
                    {
                        "type": "message",
                        "content": [{"type": "refusal", "refusal": "Unable"}],
