import Foundation

struct AnalysisAPIClient {
    func readiness() async -> AnalysisServiceStatus {
        guard let baseURL = APIConfiguration.baseURL else { return .unconfigured }
        var request = URLRequest(url: baseURL.appendingPathComponent("readyz"))
        request.timeoutInterval = 10
        request.cachePolicy = .reloadIgnoringLocalCacheData
        request.setValue(UUID().uuidString, forHTTPHeaderField: "X-Request-ID")

        do {
            let (data, response) = try await URLSession.shared.data(for: request)
            guard let httpResponse = response as? HTTPURLResponse else {
                return .unavailable(message: "The analysis service didn’t return a valid response.")
            }
            guard (200..<300).contains(httpResponse.statusCode) else {
                let detail = (try? ReportCoding.decoder.decode(ServerFailureEnvelope.self, from: data))?.detail
                return .unavailable(
                    message: UserFacingCopy.externalMessage(
                        detail?.message,
                        fallback: "The analysis service is temporarily unavailable."
                    )
                )
            }
            return .ready
        } catch {
            return .unavailable(message: "Cannot connect to the analysis service.")
        }
    }

