        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertGreaterThanOrEqual(element.frame.width, 44, file: file, line: line)
        XCTAssertGreaterThanOrEqual(element.frame.height, 44, file: file, line: line)
    }

    private func assertFullyBetweenSystemBars(
        _ element: XCUIElement,
        statusBar: XCUIElement,
        tabBar: XCUIElement,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertGreaterThanOrEqual(
            element.frame.minY,
            statusBar.frame.maxY,
            "Element intersects the status bar: element=\(element.frame), status=\(statusBar.frame)",
            file: file,
            line: line
        )
        XCTAssertLessThanOrEqual(
            element.frame.maxY,
            tabBar.frame.minY,
            "Element is covered by the floating tab bar: element=\(element.frame), tab=\(tabBar.frame)",
            file: file,
            line: line
        )
    }

    private func capture(_ name: String, app: XCUIApplication) {
