 struct OperatingPeriodComparisonAudit: Equatable {
     let warnings: [String]

     static func evaluate(
         revenue: Double?,
         orders: Int?,
         previousRevenue: Double?,
         previousOrders: Int?
     ) -> OperatingPeriodComparisonAudit {
         var warnings: [String] = []
         if let revenue, let previousRevenue, revenue > 0, previousRevenue > 0 {
             let ratio = max(revenue, previousRevenue) / min(revenue, previousRevenue)
             if ratio >= 3 {
                 warnings.append("Current period revenue differs by more than 3x from the previous period. Please check for unit errors, billing period mismatches, or duplicated channel revenue.")
             }
         }
         if let orders, let previousOrders, orders > 0, previousOrders > 0,
            let revenue, let previousRevenue, revenue > 0, previousRevenue > 0 {
             let currentTicket = revenue / Double(orders)
             let previousTicket = previousRevenue / Double(previousOrders)
             let ratio = max(currentTicket, previousTicket) / min(currentTicket, previousTicket)
             if ratio >= 2.5 {
                 warnings.append("Current period average order value differs by more than 2.5x from the previous period. Please verify order definitions and ensure top-ups and refunds are not counted as revenue.")
             }
         }
         return OperatingPeriodComparisonAudit(warnings: warnings)
     }
 }

